package limiter

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	rate     float64   // tokens per second
	burst    int       // max tokens
	tokens   float64   // current tokens
	last     time.Time // last refill time
	clock    Clock
}

// New creates a Limiter with the given refill rate (tokens/sec) and burst size.
func New(rate float64, burst int) (*Limiter, error) {
	return NewWithClock(rate, burst, realClock{})
}

// NewWithClock allows injecting a custom Clock (for tests).
func NewWithClock(rate float64, burst int, c Clock) (*Limiter, error) {
	if c == nil {
		return nil, errors.New("limiter: nil clock")
	}
	if rate <= 0 {
		return nil, errors.New("limiter: rate must be positive")
	}
	if burst <= 0 {
		return nil, errors.New("limiter: burst must be positive")
	}
	return &Limiter{
		rate:   rate,
		burst:  burst,
		tokens: float64(burst),
		clock:  c,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, refilling based on elapsed time.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	if !l.last.IsZero() {
		elapsed := now.Sub(l.last).Seconds()
		l.tokens += elapsed * l.rate
		if l.tokens > float64(l.burst) {
			l.tokens = float64(l.burst)
		}
	}
	l.last = now

	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (refilling first).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(l.clock.Now())
	return l.tokens
}

func (l *Limiter) refill(now time.Time) {
	if !l.last.IsZero() {
		elapsed := now.Sub(l.last).Seconds()
		l.tokens += elapsed * l.rate
		if l.tokens > float64(l.burst) {
			l.tokens = float64(l.burst)
		}
	}
	l.last = now
